// Extract input
const input = $json.body.input || {};
const text = input.text || '';
const format = input.format || 'markdown';

if (!text.trim()) {
  return [{
    json: {
      markdown_content: '**Error:** No text provided for summarization.',
      summary: '',
      key_points: [],
      word_count: 0
    }
  }];
}

// Count words
const words = text.trim().split(/\s+/);
const wordCount = words.length;

// Split text into sentences
// Handle common abbreviations and edge cases
const sentences = text
  .replace(/([.!?])\s+/g, '$1|SPLIT|')
  .split('|SPLIT|')
  .map(s => s.trim())
  .filter(s => s.length > 0);

// Pick first 3 sentences as key points
const keyPoints = sentences.slice(0, 3).map(s => {
  // Clean up and ensure each point ends with punctuation
  let point = s.trim();
  if (!/[.!?]$/.test(point)) {
    point += '.';
  }
  return point;
});

// Build a summary from key points
const summary = keyPoints.join(' ');

// Build markdown output
const keyPointsList = keyPoints.map((p, i) => `${i + 1}. ${p}`).join('\n');
const markdownContent = [
  '## Report Summary',
  '',
  `> ${summary}`,
  '',
  '### Key Points',
  '',
  keyPointsList,
  '',
  '---',
  `**Word count:** ${wordCount} | **Sentences analyzed:** ${sentences.length} | **Key points extracted:** ${keyPoints.length}`
].join('\n');

return [{
  json: {
    markdown_content: markdownContent,
    summary: summary,
    key_points: keyPoints,
    word_count: wordCount
  }
}];
